#include <iostream>
#include <algorithm>
#include <vector>

int main() {
    int n, q;
    if (!(std::cin >> n >> q) || n < 0 || n > 64 || q < 0 || q > 32) {
        std::cout << "invalid\n";
        return 0;
    }
    std::vector<int> values, keys;
    for (int i = 0; i < n; ++i) {
        int value;
        if (!(std::cin >> value) || value < -10000 || value > 10000) {
            std::cout << "invalid\n";
            return 0;
        }
        values.push_back(value);
    }
    for (int i = 0; i < q; ++i) {
        int key;
        if (!(std::cin >> key) || key < -10000 || key > 10000) {
            std::cout << "invalid\n";
            return 0;
        }
        keys.push_back(key);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }

    if (!std::is_sorted(values.begin(), values.end())) {
        std::cout << "unsorted\n";
        return 0;
    }
    std::cout << "queries " << q << '\n';
    // TODO: Для каждого ключа найдите обе границы и напечатайте индекс и
    // кратность.
}
